head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf10105";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf10105.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_asstHdInstCd1", fn: function () { return String((dma_pageContext.get("asstHdInstCd1") ?? "")); } },
        { childId: "ipt_asstHdInstNm1", fn: function () { return String((dma_pageContext.get("asstHdInstNm1") ?? "")); } },
        { childId: "ipt_asstHdInstCd2", fn: function () { return String((dma_pageContext.get("asstHdInstCd2") ?? "")); } },
        { childId: "ipt_asstHdInstNm2", fn: function () { return String((dma_pageContext.get("asstHdInstNm2") ?? "")); } },
        { childId: "ipt_asstHdInstCd3", fn: function () { return String((dma_pageContext.get("asstHdInstCd3") ?? "")); } },
        { childId: "ipt_asstHdInstNm3", fn: function () { return String((dma_pageContext.get("asstHdInstNm3") ?? "")); } },
        { childId: "ipt_asstHdInstCdEtc", fn: function () { return String((dma_pageContext.get("asstHdInstCdEtc") ?? "")); } },
        { childId: "ipt_asstHdTpCdEtc", fn: function () { return String((dma_pageContext.get("asstHdTpCdEtc") ?? "")); } },
        { childId: "ipt_asstAdmInstCd1", fn: function () { return String((dma_pageContext.get("asstAdmInstCd1") ?? "")); } },
        { childId: "ipt_asstAdmInstNm1", fn: function () { return String((dma_pageContext.get("asstAdmInstNm1") ?? "")); } },
        { childId: "ipt_asstAdmInstCd2", fn: function () { return String((dma_pageContext.get("asstAdmInstCd2") ?? "")); } },
        { childId: "ipt_asstAdmInstNm2", fn: function () { return String((dma_pageContext.get("asstAdmInstNm2") ?? "")); } },
        { childId: "ipt_asstAdmInstCd3", fn: function () { return String((dma_pageContext.get("asstAdmInstCd3") ?? "")); } },
        { childId: "ipt_asstAdmInstNm3", fn: function () { return String((dma_pageContext.get("asstAdmInstNm3") ?? "")); } },
        { childId: "ipt_asstAdmInstCdEtc", fn: function () { return String((dma_pageContext.get("asstAdmInstCdEtc") ?? "")); } },
        { childId: "ipt_secutizAdmInstCd", fn: function () { return String((dma_pageContext.get("secutizAdmInstCd") ?? "")); } },
        { childId: "ipt_secutizAdmInstNm", fn: function () { return String((dma_pageContext.get("secutizAdmInstNm") ?? "")); } },
        { childId: "ipt_secutizChrgNm", fn: function () { return String((dma_pageContext.get("secutizChrgNm") ?? "")); } },
        { childId: "ipt_secutizAsstTpCdEtc", fn: function () { return String((dma_pageContext.get("secutizAsstTpCdEtc") ?? "")); } },
        { childId: "ipt_secutizSchdlIsuTotamt", fn: function () { return String((dma_pageContext.get("secutizSchdlIsuTotamt") ?? "")); } },
        { childId: "ipt_secutizAsstTotValuAmt", fn: function () { return String((dma_pageContext.get("secutizAsstTotValuAmt") ?? "")); } },
        { childId: "ipt_creditRefoceMethdContn", fn: function () { return String((dma_pageContext.get("creditRefoceMethdContn") ?? "")); } },
        { childId: "ipt_secutizMiscMemoContn", fn: function () { return String((dma_pageContext.get("secutizMiscMemoContn") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
