        $c.util.getComponent('txt_totValuAmt').setValue($c.num.formatNumberKor(String(((($("#ipt_secutizAsstTotValuAmt")[0]) && ($("#ipt_secutizAsstTotValuAmt")[0]).getValue) ? ($("#ipt_secutizAsstTotValuAmt")[0]).getValue() : (((($("#ipt_secutizAsstTotValuAmt")[0]) && typeof ($("#ipt_secutizAsstTotValuAmt")[0]).val === 'function') ? ($("#ipt_secutizAsstTotValuAmt")[0]).val() : ((($("#ipt_secutizAsstTotValuAmt")[0]) && ($("#ipt_secutizAsstTotValuAmt")[0]).value !== undefined) ? ($("#ipt_secutizAsstTotValuAmt")[0]).value : ($("#ipt_secutizAsstTotValuAmt")[0]))))) == null ? '' : ((($("#ipt_secutizAsstTotValuAmt")[0]) && ($("#ipt_secutizAsstTotValuAmt")[0]).getValue) ? ($("#ipt_secutizAsstTotValuAmt")[0]).getValue() : (((($("#ipt_secutizAsstTotValuAmt")[0]) && typeof ($("#ipt_secutizAsstTotValuAmt")[0]).val === 'function') ? ($("#ipt_secutizAsstTotValuAmt")[0]).val() : ((($("#ipt_secutizAsstTotValuAmt")[0]) && ($("#ipt_secutizAsstTotValuAmt")[0]).value !== undefined) ? ($("#ipt_secutizAsstTotValuAmt")[0]).value : ($("#ipt_secutizAsstTotValuAmt")[0])))))).replace(/,/g, '')));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10105.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldinf10105: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

