/**
 * @method
 * @name initSetup
 * @description init Setup 처리
 * @returns {void}
 * @hidden N
 */
scwin.initSetup = function () {
    const tel = '' + dma_pageContext.get("secutiz_chrg_tel_no") + '';
    if (tel !== '') {
        const tels = tel.split("-");
        if (tels.length > 0) {
            $c.util.getComponent('ipt_secutizChrgTelNo1').setValue(tels[0]);
        }
        if (tels.length > 1) {
            $c.util.getComponent('ipt_secutizChrgTelNo2').setValue(tels[1]);
        }
        if (tels.length > 2) {
            $c.util.getComponent('ipt_secutizChrgTelNo3').setValue(tels[2]);
        }
    }
    const email = '' + dma_pageContext.get("encryp_secutiz_chrg_email") + '';
    if (email !== '') {
        const emails = email.split("@");
        if (emails.length > 0) {
            $c.util.getComponent('ipt_encrypSecutizChrgEmail1').setValue(emails[0]);
        }
        if (emails.length > 1) {
            $c.util.getComponent('ipt_encrypSecutizChrgEmail2').setValue(emails[1]);
        }
    }
};

/**
 * @method
 * @name emailCheck
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.emailCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^A-Za-z0-9.@_%+\\-]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

