};

/**
 * @method
 * @name send_form
 * @description send form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.send_form = async function () {
    if ($c.str.getByteLength($c.util.getComponent('ipt_asstHdInstCd1').getValue()) === 0) {
        await $c.win.alert("자산보유자 기관1을 입력하세요.");
        $c.util.getComponent("ipt_asstHdInstCd1").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_asstHdInstCdEtc').getValue()) > 80) {
        await $c.win.alert("자산보유자 기타는 한글 40자 이내로 입력하세요.");
        $c.util.getComponent("ipt_asstHdInstCdEtc").focus();
