 * @name send_cancel
 * @description send cancel 처리
 * @returns {void}
 * @hidden N
 */
scwin.send_cancel = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.delete = function (obj) {
    $('#asst_hd_inst_cd_' + obj).val("");
    $('#asst_hd_inst_nm_' + obj).val("");
};

